 engineering:[{id:'backlog',name:'Backlog',category:'planned',color:'#7d8191'},{id:'ready',name:'Ready',category:'planned',color:'#9697ab'},{id:'progress',name:'In progress',category:'started',color:'#d7a75c'},{id:'review',name:'Review',category:'started',color:'#a392e5'},{id:'done',name:'Done',category:'completed',color:'#80bfa1'}],
