function defaultWorkflowPreset(project:Project):Exclude<WorkflowPreset,'custom'>{return project.id==='campaign'||project.team==='Brandcom'?'brandcom':project.id==='pipeline'||project.team==='Business'||project.id==='partner'?'business':'engineering'}
function getProjectWorkflow(project:Project):ProjectWorkflow {return project.workflow?.stages?.length?project.workflow:{preset:defaultWorkflowPreset(project),stages:WORKFLOW_PRESETS[defaultWorkflowPreset(project)].map(s=>({...s}))}}
function issueWorkflowStage(issue:Issue,workflow:ProjectWorkflow):string {if(issue.workflowStage&&workflow.stages.some(s=>s.id===issue.workflowStage))return issue.workflowStage;const cat:WorkflowCategory=issue.status==='Done'?'completed':issue.status==='Canceled'?'canceled':issue.status==='In Progress'||issue.status==='In Review'?'started':'planned';return workflow.stages.find(s=>s.category===cat)?.id||workflow.stages[0]?.id||''}

