  const blockers=issue.blockedBy||[];const affected=allIssues.filter(i=>(i.blockedBy||[]).includes(issue.id)&&i.workspace===issue.workspace);
  const addLink=()=>{try{const u=new URL(attachmentURL.trim());if(!['https:','http:'].includes(u.protocol))throw new Error('Unsupported URL');const name=attachmentLabel.trim()||u.hostname;const v:Attachment={id:'attachment-'+Date.now().toString(36),name,kind:'link',url:u.toString()};onUpdate({attachments:[...(issue.attachments||[]),v]});setAttachmentURL('');setAttachmentLabel('');setAttachOpen(false);onNotify('Reference attached');}catch{onNotify('Enter a valid http:// or https:// link')}};
  const addFiles=(e:ChangeEvent<HTMLInputElement>)=>{const files=Array.from(e.target.files||[]).slice(0,5);if(!files.length)return;const items:Attachment[]=files.map((f,n)=>({id:'file-'+Date.now().toString(36)+'-'+n,kind:'file',name:f.name,size:f.size<1024?'Less than 1 KB':`${(f.size/1024).toFixed(0)} KB`}));onUpdate({attachments:[...(issue.attachments||[]),...items]});onNotify('File names added to prototype; no file contents uploaded');e.target.value='';};
 useEffect(()=>{setTitle(issue.title)},[issue.title]);
